select ok(exists (
  select 1 from public.task_events e join public.task_postponement_requests r
    on r.id = (e.details->>'request_id')::uuid
  where e.event_type = 'postponement_approved'
    and e.actor_id = r.decided_by and e.created_at is not null
    and e.details->>'requested_by' = r.requested_by::text
    and e.details->>'decided_by' = r.decided_by::text
    and (e.details->>'previous_due_at')::timestamptz = '2030-01-01Z'
    and (e.details->>'new_due_at')::timestamptz = r.requested_due_at
), 'approval audit contains requester, decision maker, old/new deadlines and timestamp');
